toad_implementation.code_blueprint:
canvas {
  size: 960px 600px;
  fill: #0F172A;
  font-family: "JetBrains Mono, monospace";
}

>cloudBg = #0F172A;
>ingress = #38BDF8;
>auth = #A855F7;
>database = #22C55E;
>vpcBorder = #334155;
>textMuted = #94A3B8;

text #diagramTitle {
  at: top left of canvas offset 40px 32px;
  content: "SYSTEM TOPOLOGY // EVENT-DRIVEN MICROSERVICES";
  font-size: 15px;
  font-weight: 700;
  color: #F8FAFC;
}

rect #vpcCluster {
  at: below #diagramTitle offset 24px;
  size: 880px 450px;
  fill: #1E293B;
  stroke: >vpcBorder;
  stroke-width: 2px;
  radius: 12px;
}

text #vpcTag {
  at: top left of #vpcCluster offset 20px 16px;
  content: "AWS EU-CENTRAL-1 (VPC 10.0.0.0/16)";
  font-size: 11px;
  font-weight: 700;
  color: >textMuted;
}

rect #nodeGateway {
  at: left center of #vpcCluster offset 40px 0px;
  size: 180px 120px;
  fill: #0F172A;
  stroke: >ingress;
  stroke-width: 2px;
  radius: 8px;
}

text #gwTitle {
  at: top left of #nodeGateway offset 16px 16px;
  content: "API GATEWAY";
  font-size: 13px;
  font-weight: 700;
  color: >ingress;
}

text #gwMeta {
  at: below #gwTitle offset 8px;
  content: "ENVOY PROXY\nPort: 443 HTTPS\nRate: 50k req/s";
  font-size: 11px;
  color: >textMuted;
}

rect #nodeAuth {
  at: center of #vpcCluster offset 20px -80px;
  size: 180px 120px;
  fill: #0F172A;
  stroke: >auth;
  stroke-width: 2px;
  radius: 8px;
}

text #authTitle {
  at: top left of #nodeAuth offset 16px 16px;
  content: "AUTH SERVICE";
  font-size: 13px;
  font-weight: 700;
  color: >auth;
}

text #authMeta {
  at: below #authTitle offset 8px;
  content: "OAUTH2 / JWT\ngRPC Port 50051\n3 Replicas";
  font-size: 11px;
  color: >textMuted;
}

rect #nodeDb {
  at: right center of #vpcCluster offset -40px 0px;
  size: 180px 120px;
  fill: #0F172A;
  stroke: >database;
  stroke-width: 2px;
  radius: 8px;
}

text #dbTitle {
  at: top left of #nodeDb offset 16px 16px;
  content: "POSTGRES DB";
  font-size: 13px;
  font-weight: 700;
  color: >database;
}

text #dbMeta {
  at: below #dbTitle offset 8px;
  content: "AURORA CLUSTER\nMulti-AZ Failover\nRead Replicas: 4";
  font-size: 11px;
  color: >textMuted;
}
